class Solution {
public:
    int countStableSubsequences(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        long long dp[2][2] = {{0, 0}, {0, 0}};
        for (int x : nums) {
            int p = x & 1;
            long long ndp[2][2] = {{dp[0][0], dp[0][1]}, {dp[1][0], dp[1][1]}};
            ndp[p][0] = (dp[p][0] + 1 + dp[1 - p][0] + dp[1 - p][1]) % MOD;
            ndp[p][1] = (dp[p][1] + dp[p][0]) % MOD;
            memcpy(dp, ndp, sizeof dp);
        }
        return (dp[0][0] + dp[0][1] + dp[1][0] + dp[1][1]) % (long long)MOD;
    }
};

