class Solution {
    int n;
    vector<int> *a;
    static constexpr long long MOD = 1e9 + 7;
    vector<vector<array<long long,3>>> memo;
    long long f(int i, int p, int r) {
        if (i == n) return 1;
        if (memo[i][p][r] != -1) return memo[i][p][r];
        long long res = f(i + 1, p, r);
        int q = (*a)[i] & 1;
        int nr = (p == q && r > 0) ? r + 1 : 1;
        if (nr <= 2) res = (res + f(i + 1, q, nr)) % MOD;
        return memo[i][p][r] = res;
    }
public:
    int countStableSubsequences(vector<int>& nums) {
        a = &nums; n = nums.size();
        memo.assign(n + 1, vector<array<long long,3>>(3, {-1, -1, -1}));
        return (f(0, 2, 0) - 1 + MOD) % MOD;
    }
};

