var countStableSubsequences = function(nums) {
    const MOD = 1e9 + 7, n = nums.length;
    const memo = Array.from({length: n + 1}, () => Array.from({length: 3}, () => new Array(3).fill(-1)));
    const f = (i, p, r) => {
        if (i === n) return 1;
        if (memo[i][p][r] !== -1) return memo[i][p][r];
        let res = f(i + 1, p, r);
        const q = nums[i] & 1;
        const nr = (p === q && r > 0) ? r + 1 : 1;
        if (nr <= 2) res = (res + f(i + 1, q, nr)) % MOD;
        return memo[i][p][r] = res;
    };
    return ((f(0, 2, 0) - 1) % MOD + MOD) % MOD;
};
